# Self-contained real-GPU verify of solver/vision/moe_pro.py --arch litemoe.
import sys, types, base64, io, time
import numpy as np
import torch
from PIL import Image

SRC_B64 = ''
IMG_B64 = ''

mod = types.ModuleType("moe_pro")
mod.__file__ = "moe_pro.py"
mod.__dict__["__name__"] = "moe_pro"
mod.__dict__["__file__"] = "moe_pro.py"
sys.modules["moe_pro"] = mod
exec(compile(base64.b64decode(SRC_B64).decode(), "moe_pro.py", "exec"), mod.__dict__)

im = Image.open(io.BytesIO(base64.b64decode(IMG_B64))).convert("RGB").resize((128,128))
arr = np.asarray(im).astype(np.float32).transpose(2,0,1)[None]
x = torch.from_numpy(arr).float()

cfg = mod.PRESETS["litemoe"]
net = mod.build(cfg).eval()
total = net.total_params()
active = net.active_params(x)
per = net.moe.routed_expert_params() // cfg.num_routed
print("cuda_available:", torch.cuda.is_available())
if torch.cuda.is_available():
    dev = torch.device("cuda")
    print("gpu_name:", torch.cuda.get_device_name(dev))
    net = net.to(dev).eval()
    x = x.to(dev)
    with torch.no_grad():
        for _ in range(10):
            net(x)
        t0 = time.perf_counter()
        for _ in range(50):
            logits, *_ = net(x)
        gpu_ms = (time.perf_counter() - t0) / 50 * 1000.0
    print("total_params:", int(total))
    print("active_params:", int(active))
    print("per_expert_params:", int(per))
    print("gpu_forward_ms:", round(float(gpu_ms), 2))
    print("logits_shape:", tuple(logits.shape))
    print("PASS_GPU_VERIFY")
else:
    print("NO_CUDA")
